/**
 * Junction Box Schedule Generator (sub-generator of the Cable Schedule module).
 *
 * The input is the Cable Schedule last generated by the Cable Schedule Generator (read on the server - nothing is uploaded).
 * The page lists every junction box with its connected instruments, cables and terminals; the engineer enters the total
 * terminal capacity of each box (and the few details the Cable Schedule cannot give), the server calculates terminals used,
 * spare terminals and spare %, and builds the one-sheet workbook (JB_SCHEDULE). The Junction Box Schedule is a standalone
 * deliverable: there is no cover sheet to select, upload or create.
 *
 * Every number comes from the backend (/api/cable-schedule/jb/*); this component only collects the confirmed values.
 */
import { Fragment, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, CheckCircle2, ChevronDown, ChevronRight, Download, FileSpreadsheet, ListChecks } from 'lucide-react';
import api from '@/services/api';
import Card from '../../ui/Card';
import Button from '../../ui/Button';
import Alert from '../../ui/Alert';
import GeneratedScheduleCard, { handleSourceError, useGeneratedSchedule } from './GeneratedScheduleSource';
import { DeliverableDownloads } from '../../ui/DeliverableCover';

type Cfg = Record<string, any>;
interface JB {
  jb_no: string; key: string; instrument_count: number; instruments: string[]; spare_rows: number; io_types: Record<string, number>;
  branch_cable_count: number; branch_cables: string[]; main_cable_count: number; main_cables: { tag: string; type: string; gland_size: string }[];
  branch_gland_sizes: string[]; main_gland_sizes: string[]; warnings: string[];
  terminals: { auto_available: boolean; count: number; highest: number | null; pending_count: number; pending_instruments: string[]; duplicates: string[] };
  iodb: Record<string, string[]>;
}
interface Result {
  jb_no: string; row: Record<string, any>; source: Record<string, string>; errors: string[]; warnings: string[];
  missing_generation: string[]; missing_submission: string[]; status: 'Ready' | 'Input Required' | 'Error';
  terminals_auto: number | null; terminals_auto_source: string;
}
interface Evaluation { results: Result[]; duplicates: string[]; summary: Record<string, number>; ready: boolean; submission_ready: boolean }
interface Analysis { generated: any; project_name: string; design: Design; lists: Record<string, string[]>; categories: Record<string, string>;
  analysis: { jbs: JB[]; instrument_total: number; sheets: string[]; notes: string[] }; evaluation: Evaluation }
interface Design { max_instruments: number; design_spare_pct: number }
interface Generated { filename: string; message: string; warnings: number; submission_ready: boolean; missing_for_submission: Record<string, string[]> }

const field = 'w-full border rounded-lg px-2 py-1 text-sm';
const fieldStyle = { borderColor: 'var(--b1)', background: 'var(--s1)', color: 'var(--t0)' };
const BADGE: Record<string, string> = { Ready: 'bg-green-100 text-green-700', 'Input Required': 'bg-amber-100 text-amber-700', Error: 'bg-red-100 text-red-700' };

// Details the engineer can edit for one junction box: [config key, label, list key (drop-down) or '']
const DETAILS: [string, string, string][] = [
  ['category', 'JB category', 'category'], ['jb_desc', 'JB description', ''], ['isnis', 'IS / NIS', 'isnis'], ['unit_name', 'Unit / area name', ''],
  ['location', 'Location', ''],
  ['protection', 'Enclosure protection', 'protection'], ['material', 'Enclosure material', 'material'],
  ['terminal_type', 'Terminal type', 'term_type'], ['cable_entry', 'Cable entry', 'entry'],
  ['branch_gland_size', 'Branch gland size', 'gland_size'],
  ['main_cable_no', 'Main cable no.', ''], ['main_cable_type', 'Main cable type', 'cable'],
  ['main_gland_size', 'Main cable gland size', 'gland_size'],
  ['spare_entries', 'Spare entries (qty)', ''], ['spare_entry_size', 'Spare entry size', 'gland_size'],
];
// Optional header details of the JB_SCHEDULE sheet (a blank stays blank in the workbook; nothing is filled in for you)
const HEADER_FIELDS: [string, string][] = [
  ['project_description', 'Project'], ['client', 'Client'], ['pmc', 'PMC / Consultant'], ['contractor', 'Contractor'],
  ['document_number', 'Document no.'], ['revision', 'Revision'],
];
const SOURCE_NOTE: Record<string, string> = { user: 'entered by you', '': '' };

export default function JunctionBoxScheduleGenerator() {
  const src = useGeneratedSchedule();
  const projectId = src.fields().project_id || '';
  const genId = src.gen?.id || '';
  const storeKey = `iez.jb.cfg.${projectId}.${genId}`;

  const [data, setData] = useState<Analysis | null>(null);
  const [cfg, setCfg] = useState<Record<string, Cfg>>({});
  const [design, setDesign] = useState<Design | null>(null);
  const [hdr, setHdr] = useState<Record<string, string>>({});
  const [ev, setEv] = useState<Evaluation | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const [picked, setPicked] = useState<string[]>([]);
  const [bulk, setBulk] = useState('');
  const [analyzing, setAnalyzing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<Generated | null>(null);
  const seq = useRef(0);

  // the confirmed values survive a page change inside the session (they are tied to this generated Cable Schedule)
  useEffect(() => {
    setData(null); setEv(null); setResult(null); setOpen(null); setPicked([]);
    try { setCfg(JSON.parse(sessionStorage.getItem(storeKey) || '{}')); } catch { setCfg({}); }
  }, [storeKey]);
  useEffect(() => { try { sessionStorage.setItem(storeKey, JSON.stringify(cfg)); } catch { /* storage unavailable */ } }, [cfg, storeKey]);
  const hdrKey = `iez.jb.hdr.${projectId}`;
  useEffect(() => { try { setHdr(JSON.parse(sessionStorage.getItem(hdrKey) || '{}')); } catch { setHdr({}); } }, [hdrKey]);
  useEffect(() => { try { sessionStorage.setItem(hdrKey, JSON.stringify(hdr)); } catch { /* storage unavailable */ } }, [hdr, hdrKey]);

  const body = useCallback(() => ({ project_id: projectId || null, generated_id: genId || null, jbs: cfg, design, header: hdr }), [projectId, genId, cfg, design, hdr]);

  const analyze = async () => {
    setAnalyzing(true); setError(null); setResult(null);
    try {
      const r = await api.post<Analysis>('/cable-schedule/jb/analyze', body());
      setData(r.data); setEv(r.data.evaluation); setDesign((d) => d ?? r.data.design);
      // the registered project name pre-fills the PROJECT header field once; the engineer can change or clear it
      if (r.data.project_name) setHdr((h) => (h.project_description === undefined ? { ...h, project_description: r.data.project_name } : h));
    } catch (e: any) { handleSourceError(e, src, setError, 'Could not analyze the junction boxes.'); }
    finally { setAnalyzing(false); }
  };

  // every change is recalculated by the server (debounced): terminals used, spare terminals, spare %, errors, warnings
  useEffect(() => {
    if (!data) return;
    const n = ++seq.current;
    const t = window.setTimeout(() => {
      api.post<{ evaluation: Evaluation }>('/cable-schedule/jb/validate', body())
        .then((r) => { if (n === seq.current) setEv(r.data.evaluation); })
        .catch((e) => { if (n === seq.current) handleSourceError(e, src, setError, 'Could not validate.'); });
    }, 400);
    return () => window.clearTimeout(t);
  }, [cfg, design]); // eslint-disable-line react-hooks/exhaustive-deps

  const patch = (jb: string, p: Cfg) => setCfg((c) => ({ ...c, [jb]: { ...(c[jb] || {}), ...p } }));
  const jbs = data?.analysis.jbs ?? [];
  const results = useMemo(() => Object.fromEntries((ev?.results ?? []).map((r) => [r.jb_no, r])), [ev]);

  const applyBulk = () => {
    const n = Number(bulk);
    if (!Number.isInteger(n) || n < 1) { setError('The terminal capacity must be a whole number greater than zero.'); return; }
    setError(null);
    setCfg((c) => { const next = { ...c }; picked.forEach((jb) => { next[jb] = { ...(next[jb] || {}), terminal_capacity: n }; }); return next; });
  };

  const generate = async () => {
    setGenerating(true); setError(null); setResult(null);
    try {
      const r = await api.post<Generated & { evaluation: Evaluation }>('/cable-schedule/jb/generate', body());
      setResult(r.data); setEv(r.data.evaluation);
    } catch (e: any) {
      const d = e.response?.data?.detail;
      if (d && typeof d === 'object') { setError(d.message || 'Generation was refused.'); if (d.evaluation) setEv(d.evaluation); }
      else handleSourceError(e, src, setError, 'Generation failed.');
    } finally { setGenerating(false); }
  };

  const download = async () => {
    try {
      const r = await api.get('/cable-schedule/jb/download', { responseType: 'blob' });
      const a = document.createElement('a');
      a.href = window.URL.createObjectURL(new Blob([r.data]));
      a.setAttribute('download', result?.filename || 'Junction_Box_Schedule.xlsx');
      document.body.appendChild(a); a.click(); a.remove();
    } catch (e: any) { setError(e.response?.data?.detail || 'Download failed.'); }
  };

  const missingGen = useMemo(() => {
    const m: Record<string, string[]> = {};
    (ev?.results ?? []).forEach((r) => r.missing_generation.forEach((f) => { (m[f] ||= []).push(r.jb_no); }));
    return m;
  }, [ev]);
  const missingSub = useMemo(() => {
    const m: Record<string, string[]> = {};
    (ev?.results ?? []).forEach((r) => r.missing_submission.forEach((f) => { (m[f] ||= []).push(r.jb_no); }));
    return m;
  }, [ev]);
  const canGenerate = !!ev?.ready && !generating;               // depends only on the engineering inputs
  const num = (v: any) => (v === null || v === undefined || v === '' ? '—' : v);

  return (
    <div className="space-y-6" data-testid="jb-schedule">
      <GeneratedScheduleCard state={src} title="Section 1 — Input Source: Generated Cable Schedule">
        <div className="pt-2">
          <Button onClick={analyze} loading={analyzing} disabled={!src.gen?.available}><ListChecks className="w-4 h-4" />Analyze Junction Boxes</Button>
          {analyzing && <p className="text-xs mt-2" style={{ color: 'var(--t1)' }}>Reading the Cable Schedule on the server… a large schedule can take about 10 seconds.</p>}
        </div>
      </GeneratedScheduleCard>

      {error && <Alert variant="error" title="Error" onClose={() => setError(null)}>{error}</Alert>}

      {data && (
        <>
          <Card title="Section 2 — Junction Box Analysis" icon={FileSpreadsheet}
                description="Counted from the generated Cable Schedule: unique instrument tags and unique physical cables per junction box.">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm mb-3">
              <div><p className="text-xs" style={{ color: 'var(--t2)' }}>Project</p><p className="font-semibold" style={{ color: 'var(--t0)' }}>{projectId || '—'}</p></div>
              <div><p className="text-xs" style={{ color: 'var(--t2)' }}>Junction boxes</p><p className="font-semibold" style={{ color: 'var(--t0)' }} data-testid="jb-count">{jbs.length}</p></div>
              <div><p className="text-xs" style={{ color: 'var(--t2)' }}>Instruments</p><p className="font-semibold" style={{ color: 'var(--t0)' }}>{data.analysis.instrument_total}</p></div>
              <div><p className="text-xs" style={{ color: 'var(--t2)' }}>Status</p>
                <p className="font-semibold" style={{ color: 'var(--t0)' }}>{ev ? Object.entries(ev.summary).map(([k, v]) => `${v} ${k}`).join(' · ') : '…'}</p></div>
            </div>
            {data.analysis.notes.map((n, i) => <p key={i} className="text-xs text-amber-600 mb-1">{n}</p>)}

            {/* convenience: one capacity for many boxes - each box stays individually editable */}
            <div className="flex flex-wrap items-center gap-2 mb-3 text-sm" style={{ color: 'var(--t1)' }}>
              <span>Apply total terminal capacity</span>
              <input className={`${field} w-24`} style={fieldStyle} value={bulk} inputMode="numeric" placeholder="ways" aria-label="Capacity for the selected junction boxes"
                     onChange={(e) => setBulk(e.target.value)} />
              <span>to the {picked.length} selected box(es)</span>
              <Button variant="secondary" size="sm" onClick={applyBulk} disabled={!picked.length || !bulk}>Apply</Button>
              <button className="underline text-xs" onClick={() => setPicked(picked.length === jbs.length ? [] : jbs.map((j) => j.jb_no))}>
                {picked.length === jbs.length ? 'Clear selection' : 'Select all'}</button>
            </div>

            <div className="overflow-auto border rounded-lg max-h-[34rem]" style={{ borderColor: 'var(--b1)' }}>
              <table className="w-full text-xs">
                <thead className="sticky top-0" style={{ background: 'var(--s2)' }}>
                  <tr>{['', '', 'JB No.', 'Category', 'IS/NIS', 'Instruments', 'Branch cables', 'Main cables', 'Terminals used', 'Total capacity (ways)', 'Spare', 'Spare %', 'Status']
                    .map((h, i) => <th key={i} className="px-2 py-1.5 text-left font-medium whitespace-nowrap" style={{ color: 'var(--t1)' }}>{h}</th>)}</tr>
                </thead>
                <tbody>
                  {jbs.map((j) => {
                    const r = results[j.jb_no];
                    const isOpen = open === j.jb_no;
                    return (
                      <Fragment key={j.jb_no}>
                        <tr className="border-t" style={{ borderColor: 'var(--b1)', color: 'var(--t0)' }} data-testid={`jb-row-${j.jb_no}`}>
                          <td className="px-2 py-1"><input type="checkbox" checked={picked.includes(j.jb_no)} aria-label={`Select ${j.jb_no}`}
                              onChange={() => setPicked((p) => (p.includes(j.jb_no) ? p.filter((x) => x !== j.jb_no) : [...p, j.jb_no]))} /></td>
                          <td className="px-1"><button onClick={() => setOpen(isOpen ? null : j.jb_no)} aria-label={`Details of ${j.jb_no}`}>
                            {isOpen ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}</button></td>
                          <td className="px-2 py-1 font-mono whitespace-nowrap">{j.jb_no}</td>
                          <td className="px-2 py-1">{r?.row.category || <span className="text-amber-600">select</span>}</td>
                          <td className="px-2 py-1">{r?.row.isnis || '—'}</td>
                          <td className="px-2 py-1">{j.instrument_count}</td>
                          <td className="px-2 py-1">{j.branch_cable_count}</td>
                          <td className="px-2 py-1">{j.main_cable_count}</td>
                          <td className="px-2 py-1" title={r?.source.terminals_used}>{r?.row.terminals_used ?? <span className="text-amber-600">needed</span>}
                            {r && r.row.terminals_method !== 'auto' && <span className="text-[10px] ml-1" style={{ color: 'var(--t2)' }}>(user)</span>}</td>
                          <td className="px-2 py-1">
                            <input className={`${field} w-24`} style={fieldStyle} inputMode="numeric" value={cfg[j.jb_no]?.terminal_capacity ?? ''}
                                   aria-label={`Total terminal capacity of ${j.jb_no}`} placeholder="ways"
                                   onChange={(e) => patch(j.jb_no, { terminal_capacity: e.target.value })} />
                          </td>
                          <td className="px-2 py-1">{num(r?.row.spare_terminals)}</td>
                          <td className="px-2 py-1">{r?.row.spare_pct == null ? '—' : `${(r.row.spare_pct * 100).toFixed(1)}%`}</td>
                          <td className="px-2 py-1"><span className={`px-2 py-0.5 rounded-full text-[11px] font-semibold ${BADGE[r?.status || 'Input Required']}`}>{r?.status || '…'}</span></td>
                        </tr>
                        {isOpen && r && (
                          <tr style={{ background: 'var(--s2)' }}><td colSpan={13} className="px-4 py-3">
                            <Detail j={j} r={r} cfg={cfg[j.jb_no] || {}} lists={data.lists} onChange={(p) => patch(j.jb_no, p)} />
                          </td></tr>
                        )}
                      </Fragment>
                    );
                  })}
                </tbody>
              </table>
            </div>
            <p className="text-xs mt-2" style={{ color: 'var(--t2)' }}>Open a row (arrow) to see its instruments and cables, choose how terminals used are determined, and edit the other junction box details.</p>
          </Card>

          <Card title="Section 3 — Additional Junction Box Information Required" icon={AlertTriangle}
                description="Only what cannot be taken reliably from the Cable Schedule. Nothing is guessed - missing values stay blank.">
            {Object.keys(missingGen).length === 0 && Object.keys(missingSub).length === 0
              ? <p className="text-sm text-green-600 flex items-center gap-1.5"><CheckCircle2 className="w-4 h-4" />Nothing further is required.</p>
              : (
                <div className="space-y-3 text-sm" style={{ color: 'var(--t1)' }}>
                  {Object.keys(missingGen).length > 0 && (
                    <div><p className="font-semibold text-amber-700 mb-1">Required to generate</p>
                      <ul className="list-disc pl-5 space-y-0.5">{Object.entries(missingGen).map(([f, l]) => <li key={f}><strong>{f}</strong> - {l.length} box(es): {l.slice(0, 6).join(', ')}{l.length > 6 ? ' …' : ''}</li>)}</ul></div>)}
                  {Object.keys(missingSub).length > 0 && (
                    <div><p className="font-semibold mb-1" style={{ color: 'var(--t0)' }}>Needed before client submission (does not block generation)</p>
                      <ul className="list-disc pl-5 space-y-0.5">{Object.entries(missingSub).map(([f, l]) => <li key={f}><strong>{f}</strong> - {l.length} box(es){l.length <= 6 ? `: ${l.join(', ')}` : ''}</li>)}</ul></div>)}
                </div>)}
            {design && (
              <details className="mt-3 text-sm" style={{ color: 'var(--t1)' }}>
                <summary className="cursor-pointer">Design parameters used by the review warnings (from the standard template)</summary>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-2">
                  <label>Max instruments per JB<input className={field} style={fieldStyle} value={design.max_instruments} onChange={(e) => setDesign({ ...design, max_instruments: Number(e.target.value) || 0 })} /></label>
                  <label>Design spare terminals (fraction)<input className={field} style={fieldStyle} value={design.design_spare_pct} onChange={(e) => setDesign({ ...design, design_spare_pct: Number(e.target.value) || 0 })} /></label>
                </div>
              </details>)}
          </Card>

          <Card title="Section 4 — Review, Generate & Download" icon={Download}
                description="The Junction Box Schedule workbook (JB_SCHEDULE).">
            <details className="text-sm" style={{ color: 'var(--t1)' }} data-testid="jb-header-details">
              <summary className="cursor-pointer font-medium" style={{ color: 'var(--t0)' }}>Document header details (optional)</summary>
              <p className="text-xs mt-1" style={{ color: 'var(--t2)' }}>Written into the header of the JB_SCHEDULE sheet. Anything left blank stays blank; the date is the generation date.</p>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mt-2">
                {HEADER_FIELDS.map(([k, label]) => (
                  <label key={k}>{label}<input className={field} style={fieldStyle} value={hdr[k] ?? ''} maxLength={200} data-testid={`jb-hdr-${k}`}
                    onChange={(e) => setHdr({ ...hdr, [k]: e.target.value })} /></label>))}
              </div>
            </details>
            {ev && (ev.results.some((r) => r.warnings.length || r.errors.length)) && (
              <details className="mt-3 text-sm" open={ev.results.some((r) => r.errors.length)}>
                <summary className="cursor-pointer font-medium" style={{ color: 'var(--t0)' }}>
                  Review items ({ev.results.reduce((n, r) => n + r.errors.length + r.warnings.length, 0)})</summary>
                <ul className="mt-2 space-y-1 max-h-64 overflow-auto">
                  {ev.results.flatMap((r) => [...r.errors.map((m) => ({ jb: r.jb_no, m, e: true })), ...r.warnings.map((m) => ({ jb: r.jb_no, m, e: false }))])
                    .map((x, i) => <li key={i} className={x.e ? 'text-red-600' : 'text-amber-700'}><span className="font-mono">{x.jb}</span> - {x.m}</li>)}
                </ul>
              </details>)}
            <div className="flex flex-wrap gap-2 mt-4">
              <Button variant="secondary" onClick={analyze} loading={analyzing}>Validate</Button>
              <Button onClick={generate} loading={generating} disabled={!canGenerate} data-testid="jb-generate">Generate Junction Box Schedule</Button>
            </div>
            {!canGenerate && !generating && (
              <p className="text-xs mt-2" style={{ color: 'var(--t2)' }}>
                {ev?.duplicates.length ? 'A junction box appears twice.'
                  : `${(ev?.summary['Input Required'] || 0) + (ev?.summary['Error'] || 0)} junction box(es) still need input or have an error.`}</p>)}
            {generating && <p className="text-xs mt-2" style={{ color: 'var(--t1)' }}>Building the workbook…</p>}
            {result && (
              <div className="mt-4 space-y-3" data-testid="jb-result">
                <Alert variant="success" title="Junction Box Schedule generated">
                  {result.message} {result.warnings > 0 && `${result.warnings} review item(s) remain.`}
                  {!result.submission_ready && ' Some details needed for client submission are still blank (see Section 3).'}
                </Alert>
                <DeliverableDownloads module={'jb_schedule' as any} filename={result.filename} onExcel={download} />
              </div>)}
          </Card>
        </>
      )}
    </div>
  );
}

/** The expandable panel of one junction box: what the Cable Schedule has, how terminals used are determined, editable details. */
function Detail({ j, r, cfg, lists, onChange }: { j: JB; r: Result; cfg: Cfg; lists: Record<string, string[]>; onChange: (p: Cfg) => void }) {
  const method = cfg.terminals_method || 'auto';
  const t = j.terminals;
  return (
    <div className="space-y-4 text-xs" style={{ color: 'var(--t1)' }}>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div>
          <p className="font-semibold mb-1" style={{ color: 'var(--t0)' }}>Instruments ({j.instrument_count})</p>
          <p className="max-h-24 overflow-auto font-mono">{j.instruments.join(', ') || '—'}</p>
          {j.spare_rows > 0 && <p className="mt-1">{j.spare_rows} spare row(s) are not counted as instruments.</p>}
          <p className="mt-2">Signal types: {Object.entries(j.io_types).map(([k, v]) => `${k} ×${v}`).join(', ') || '—'}</p>
        </div>
        <div>
          <p className="font-semibold mb-1" style={{ color: 'var(--t0)' }}>Cables</p>
          <p>Branch cables ({j.branch_cable_count}): <span className="font-mono">{j.branch_cables.slice(0, 12).join(', ')}{j.branch_cables.length > 12 ? ' …' : ''}</span></p>
          <p className="mt-1">Main cables ({j.main_cable_count}): <span className="font-mono">{j.main_cables.map((m) => `${m.tag}${m.type ? ` (${m.type})` : ''}`).slice(0, 8).join(', ')}{j.main_cables.length > 8 ? ' …' : ''}</span></p>
          <p className="mt-1">Glands in the schedule - branch: {j.branch_gland_sizes.join(', ') || '—'}; main: {j.main_gland_sizes.join(', ') || '—'}</p>
        </div>
        <div>
          <p className="font-semibold mb-1" style={{ color: 'var(--t0)' }}>Terminals used</p>
          <p>{t.auto_available ? `${r.terminals_auto ?? t.count} from the Cable Schedule (${r.terminals_auto_source || 'terminal rows'}); highest terminal no. ${t.highest ?? '—'}` : 'The Cable Schedule has no complete terminal numbers for this box.'}</p>
          {!t.auto_available && t.pending_count > 0 && <p className="text-amber-700">{t.pending_count} instrument(s) have no terminal numbers yet.</p>}
          <div className="mt-2 space-y-1">
            {[['auto', 'From the Cable Schedule' + (r.row.category === 'SMB' ? ' (ways = instruments)' : '')], ['per_instrument', 'Terminals per instrument (I confirm)'], ['manual', 'Total used terminals (I confirm)']].map(([k, label]) => (
              <label key={k} className="flex items-center gap-2 cursor-pointer">
                <input type="radio" name={`m-${j.jb_no}`} checked={method === k} onChange={() => onChange({ terminals_method: k })} />{label}
                {k === 'per_instrument' && method === k && <input className={`${field} w-16`} style={fieldStyle} inputMode="numeric" value={cfg.terminals_per_instrument ?? ''}
                    aria-label={`Terminals per instrument for ${j.jb_no}`} onChange={(e) => onChange({ terminals_per_instrument: e.target.value })} />}
                {k === 'manual' && method === k && <input className={`${field} w-16`} style={fieldStyle} inputMode="numeric" value={cfg.terminals_manual ?? ''}
                    aria-label={`Total used terminals of ${j.jb_no}`} onChange={(e) => onChange({ terminals_manual: e.target.value })} />}
              </label>))}
          </div>
        </div>
      </div>
      {[...r.errors.map((m) => ({ m, e: true })), ...r.warnings.map((m) => ({ m, e: false }))].map((x, i) => (
        <p key={i} className={x.e ? 'text-red-600' : 'text-amber-700'}>{x.e ? 'Error' : 'Review'}: {x.m}</p>))}
      <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
        {DETAILS.map(([key, label, listKey]) => {
          // several main cables: one value per cable, in order, separated by ';' (a single drop-down cannot hold them)
          const perCable = j.main_cable_count > 1 && key.startsWith('main_');
          const list = perCable ? '' : listKey;
          const shown = cfg[key] ?? String(r.row[key] ?? '').split('\n').join('; ');
          const from = cfg[key] ? SOURCE_NOTE.user : r.source[key] ? `from ${r.source[key]}` : '';
          return (
            <label key={key} className="block">
              <span className="block mb-0.5">{label}{perCable && <span className="ml-1 text-[10px]">(one per cable, separated by ;)</span>}{from && <span className="ml-1 text-[10px]" style={{ color: 'var(--t2)' }}>({from})</span>}</span>
              {list ? (
                <select className={field} style={fieldStyle} value={shown} onChange={(e) => onChange({ [key]: e.target.value })}>
                  <option value="">—</option>
                  {[...(lists[list] || []), ...(shown && !(lists[list] || []).includes(shown) ? [shown] : [])].map((o) => <option key={o} value={o}>{o}</option>)}
                </select>
              ) : (
                <input className={field} style={fieldStyle} value={shown} onChange={(e) => onChange({ [key]: e.target.value })} />
              )}
            </label>);
        })}
      </div>
    </div>
  );
}
